pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params: choose a variety of inputs to initialize; keep domains wide
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep feeRate in a normal range but allow wide exploration; ensure admissible: feeRate <= max allowed
        // If feeRate > 5000 the reference reverts FeeRateTooHigh — that's allowed, but property is about a single successful initialize leading to initialized()==true when initialize does not revert.
        // We'll call initialize and observe whether it returns (ok=true) and then check initialized flag if it returned.

        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if initialize returned successfully (did not revert), then c.initialized() must be true.
        // The mutant can make initialize revert unconditionally or in surprising ways; the single assertion reads c via its public getter.
        if (ok) {
            assertTrue(c.initialized());
        } else {
            // If initialize reverted, we still assert something that the reference satisfies for all inputs: when initialize reverts because of FeeRateTooHigh (feeRate>5000), the reference also reverts; but to keep a single assertion required by the harness, assertTrue(!ok || c.initialized());
            // However test harness requires exactly one assertTrue reading c. The branch above already asserts when ok. For the else branch, we need a single assertTrue overall.
            // To satisfy the requirement of exactly one assertTrue, move to single final assertion below.
        }

        // Single assertion required by the problem: for any call that returned (ok==true), c.initialized() must be true.
        // This single assertion covers both cases: if ok==false the implication is vacuously true; if ok==true it enforces the getter.
        assertTrue(!ok || c.initialized());
    }
}

