    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz over inputs to initialize; the fuzzer will search for inputs that make the mutant revert
    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // keep parameters wide but ensure reasonable ranges for feeRate (already checked in contract)
        // do not over-constrain; allow fuzzer to find problematic values
        // Make the call as an EOA (this) — initialize is public and should succeed on reference

        bool ok;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
